<?php $q=trim($_GET['q']??'');$st=$pdo->prepare('SELECT b.*, (SELECT COUNT(*) FROM loans l WHERE l.borrower_id=b.id AND l.returned_at IS NULL) active_count FROM borrowers b WHERE (?=\'\' OR b.full_name LIKE ? OR b.phone LIKE ? OR b.email LIKE ?) ORDER BY b.full_name');$st->execute([$q,"%$q%","%$q%","%$q%"]);$rows=$st->fetchAll();layout_start('Borrowers','borrowers'); ?><div class="page-heading"><div><p class="eyebrow">PEOPLE</p><h1>Borrowers</h1><p class="muted">Manage contact details and lending history.</p></div><a class="button primary" href="?page=borrower-form">＋ Add borrower</a></div><section class="panel"><form method="get" class="filter-bar"><input type="hidden" name="page" value="borrowers"><label class="search-box"><span>⌕</span><input name="q" value="<?=h($q)?>" placeholder="Search by name, phone or email"></label><button class="button secondary">Search</button></form><div class="table-scroll"><table><thead><tr><th>Borrower</th><th>Contact</th><th>Registered</th><th>Active loans</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?=h($r['full_name'])?></strong></td><td><?=h($r['phone'])?><small class="cell-sub"><?=h($r['email'])?></small></td><td><?=date('j M Y',strtotime($r['registered_at']))?></td><td><?=$r['active_count']?></td><td><span class="badge <?=strtolower($r['status'])?>"><?=h($r['status'])?></span></td><td><a class="text-link" href="?page=borrower-view&id=<?=$r['id']?>">View →</a></td></tr><?php endforeach; ?></tbody></table><?php if(!$rows): ?><div class="table-empty">No borrower records found.</div><?php endif; ?></div></section><?php layout_end();
